const magenta = '#ff00a8';
const black = 0x111111;
const C_POS = new THREE.Vector3(-1.7, 0.22, 0);

function clamp01(v) { return Math.max(0, Math.min(1, v)); }
function midWeight(t) { return clamp01(1 - Math.abs(t - 0.5) * 2); }
function lerpVec(a, b, u) { return a.clone().lerp(b, u); }
function twoPhaseVec(a, b, c, t) {
  return t <= 0.5 ? lerpVec(a, b, t * 2) : lerpVec(b, c, (t - 0.5) * 2);
}
function hexColor(hex) { return new THREE.Color(hex); }
function mixColor(a, b, u) { return hexColor(a).lerp(hexColor(b), clamp01(u)); }

function matPhong(color, opacity, extra = {}) {
  return new THREE.MeshPhongMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 0.85,
    shininess: 55,
    side: THREE.DoubleSide,
    ...extra
  });
}

function makeSphere(r, color, opacity = 1, segments = 48) {
  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(r, segments, Math.max(16, segments / 2)),
    matPhong(color, opacity)
  );
  return mesh;
}

function makeLine(color = black, dashed = false, opacity = 1, width = 1) {
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.07, gapSize: 0.045, transparent: true, opacity, linewidth: width })
    : new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity, linewidth: width });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3(1, 0, 0)]), mat);
  scene.add(line);
  return line;
}

function setLine(line, a, b) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints([a, b]);
  old.dispose();
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}

const surfaceGroup = new THREE.Group();
const atomGroup = new THREE.Group();
scene.add(surfaceGroup, atomGroup);

const nuSurf = makeSphere(0.45, 0xc43126, 0.56, 64);
