  items.push(createFlatLine([new THREE.Vector3(lx, y0, z), new THREE.Vector3(lx + 0.08, y0, z)], black));
  items.push(createFlatLine([new THREE.Vector3(rx, y0, z), new THREE.Vector3(rx, y1, z)], black));
  items.push(createFlatLine([new THREE.Vector3(rx, y1, z), new THREE.Vector3(rx - 0.08, y1, z)], black));
  items.push(createFlatLine([new THREE.Vector3(rx, y0, z), new THREE.Vector3(rx - 0.08, y0, z)], black));
  return { items, labelData: [
    ['Nu', new THREE.Vector3(2.52, 0.32, z), { color: magenta, fontSize: '19px' }],
