function moleculePositions(t) {
  const nu = new THREE.Vector3(
    t <= 0.5 ? THREE.MathUtils.lerp(-3.8, C_POS.x - 1.15, t * 2) : THREE.MathUtils.lerp(C_POS.x - 1.15, C_POS.x - 1.05, (t - 0.5) * 2),
    C_POS.y,
    0
  );
  const x = new THREE.Vector3(
    t <= 0.5 ? THREE.MathUtils.lerp(C_POS.x + 1.15, C_POS.x + 1.15, t * 2) : THREE.MathUtils.lerp(C_POS.x + 1.15, C_POS.x + 1.70, (t - 0.5) * 2),
    C_POS.y,
    0
  );
  const subs = rSub.map((v, i) => twoPhaseVec(v, tsSub[i], pSub[i], t).add(C_POS));
  return { nu, c: C_POS.clone(), x, subs };
}

function setMatOpacity(obj, opacity) {
  obj.material.transparent = opacity < 1;
  obj.material.opacity = opacity;
  obj.material.depthWrite = opacity >= 0.85;
  obj.visible = opacity > 0.01;
}

function setLineOpacity(line, opacity) {
  line.material.transparent = true;
  line.material.opacity = opacity;
  line.visible = opacity > 0.01;
}

function createFlatLine(points, color = black, opacity = 1, dashed = false) {
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.055, gapSize: 0.045, transparent: true, opacity })
    : new THREE.LineBasicMaterial({ color, transparent: true, opacity });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), mat);
  if (dashed) line.computeLineDistances();
  scene.add(line);
  return line;
}

function createWedge(c, end, width = 0.08, color = black) {
  const dir = end.clone().sub(c).normalize();
  const perp = new THREE.Vector3(-dir.y, dir.x, 0).multiplyScalar(width);
  const geom = new THREE.BufferGeometry().setFromPoints([c, end.clone().add(perp), end.clone().sub(perp)]);
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, transparent: true, opacity: 1 }));
  scene.add(mesh);
  return mesh;
}

function createHashed(c, end, color = black) {
  const g = new THREE.Group();
  scene.add(g);
  const dir = end.clone().sub(c);
  const n = new THREE.Vector3(-dir.y, dir.x, 0).normalize();
  for (let i = 1; i <= 6; i++) {
    const f = i / 7;
    const mid = c.clone().lerp(end, f);
    const half = 0.012 + 0.045 * f;
    const ln = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([mid.clone().addScaledVector(n, -half), mid.clone().addScaledVector(n, half)]),
      new THREE.LineBasicMaterial({ color, transparent: true, opacity: 1 })
    );
    g.add(ln);
  }
  return g;
}

function setObjectOpacity(obj, opacity) {
  obj.traverse(o => {
    if (o.material) {
      o.material.transparent = true;
      o.material.opacity = opacity;
    }
    o.visible = opacity > 0.015;
  });
}

