function updateProgressGeometry(t) {
  const pos = moleculePositions(t);
  const wMid = midWeight(t);
  const wR = clamp01(1 - t * 2);
  const wP = clamp01(t * 2 - 1);

  atomNu.position.copy(pos.nu);
  atomC.position.copy(pos.c);
  atomX.position.copy(pos.x);
  for (let i = 0; i < 3; i++) {
    subAtoms[i].position.copy(pos.subs[i]);
    smallSurfaceBlobs[i].position.copy(pos.subs[i]);
    const surfaceScale = 1.0 + 0.35 * wMid;
    smallSurfaceBlobs[i].scale.set(surfaceScale, surfaceScale, surfaceScale);
    setLine(subBonds[i], pos.c, pos.subs[i]);
  }

  setLine(nuBondSolid, pos.nu, pos.c);
  setLine(xBondSolid, pos.c, pos.x);
  setLine(nuBondDash, pos.nu, pos.c);
  setLine(xBondDash, pos.c, pos.x);

  setLineOpacity(nuBondSolid, clamp01((t - 0.52) / 0.42));
  setLineOpacity(xBondSolid, clamp01(1 - t / 0.46));
  setLineOpacity(nuBondDash, wMid * 0.95);
  setLineOpacity(xBondDash, wMid * 0.95);

  nuSurf.position.copy(pos.nu);
  cSurf.position.copy(pos.c);
  xSurf.position.copy(pos.x);
  bridgeSurf.position.copy(pos.c);
  bridgeSurf.scale.set(1.35, 0.62 + 0.08 * wMid, 0.50 + 0.12 * wMid);

  const nuRadius = THREE.MathUtils.lerp(0.58, 0.42, t);
  nuSurf.scale.set(nuRadius / 0.45, nuRadius / 0.45, nuRadius / 0.45);
  const xRadius = THREE.MathUtils.lerp(0.55, 0.72, t);
  xSurf.scale.set(xRadius / 0.55, xRadius / 0.55, xRadius / 0.55);
  cSurf.scale.set(0.95 + 0.42 * wMid, 0.74 + 0.23 * wMid, 0.68 + 0.20 * wMid);

  nuSurf.material.color.copy(mixColor('#e86b6b', '#8bcf8d', clamp01(t * 0.9)));
  xSurf.material.color.copy(mixColor('#c4472f', '#e86b6b', clamp01(t + 0.15)));
  cSurf.material.color.copy(mixColor('#8bcf8d', '#f2e76a', wMid * 0.9));
  bridgeSurf.material.color.copy(mixColor('#8bcf8d', '#f2e76a', 0.55 + 0.35 * wMid));
  setMatOpacity(bridgeSurf, 0.08 + 0.40 * wMid);
  setMatOpacity(nuSurf, 0.52 - 0.08 * t + 0.08 * wMid);
  setMatOpacity(xSurf, 0.44 + 0.15 * t + 0.08 * wMid);
  setMatOpacity(cSurf, 0.34 + 0.16 * wMid);
  smallSurfaceBlobs.forEach((s, i) => {
    s.material.color.copy(i === 0 ? mixColor('#657ad8', '#8bcf8d', t) : mixColor('#8bcf8d', '#f2e76a', wMid));
    setMatOpacity(s, 0.20 + 0.13 * wMid);
  });

  const oR = clamp01(1 - t / 0.45);
  const oTS = wMid;
  const oP = clamp01((t - 0.55) / 0.45);
  setObjectOpacity({ traverse: f => skelReact.items.forEach(it => it.traverse ? it.traverse(f) : f(it)) }, oR);
  setObjectOpacity({ traverse: f => skelTS.items.forEach(it => it.traverse ? it.traverse(f) : f(it)) }, oTS);
  setObjectOpacity({ traverse: f => skelProd.items.forEach(it => it.traverse ? it.traverse(f) : f(it)) }, oP);

  progressMarker.position.set(guideX, THREE.MathUtils.lerp(1.18, -1.10, t), gz);

  if (mapGeomLabel) {
    mapGeomLabel.div.innerHTML = wMid > 0.55 ? '<b>Planar</b>' : '<b>Tetrahedral</b>';
    mapGeomLabel.pos.set(-1.7, -1.18, 0);
  }
  if (stageLabel) {
    if (t < 0.28) stageLabel.div.innerHTML = 'Reactants: backside approach';
    else if (t < 0.72) stageLabel.div.innerHTML = 'Transition state: planar carbon';
    else stageLabel.div.innerHTML = 'Products: inverted tetrahedron';
  }
  if (skelReact.labels) setLabelOpacity(skelReact.labels, oR);
  if (skelTS.labels) setLabelOpacity(skelTS.labels, oTS);
  if (skelProd.labels) setLabelOpacity(skelProd.labels, oP);
}

