let tweenId = 0;
function tweenTo(target) {
  const slider = document.getElementById('reactionProgress');
  const start = Number(slider.value);
  const id = ++tweenId;
  const t0 = performance.now();
  const dur = 850;
  function step(now) {
    if (id !== tweenId) return;
    const u = clamp01((now - t0) / dur);
    const ease = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    updateProgress(THREE.MathUtils.lerp(start, target, ease));
    if (u < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

window.goToStep = function goToStep(i) {
  const steps = [0, 0.5, 1];
  const titles = ['Reactants: backside approach', 'Transition state: planar carbon', 'Products: inverted tetrahedron'];
  const bodies = [
    'The nucleophile starts as a separate red, electron-rich sphere on the side opposite the leaving group. The carbon is tetrahedral and still bonded to X.',
    'At the midpoint, Nu and X are both partially bonded to carbon. The three other substituents lie in a plane, and red electrostatic potential appears at both ends.',
    'The Nu–C bond is complete and X has departed with the negative charge. The tetrahedral arrangement has inverted relative to the starting alkyl halide.'
  ];
  const idx = Math.max(0, Math.min(2, i | 0));
  tweenTo(steps[idx]);
  showPopup(titles[idx], bodies[idx]);
};

document.getElementById('reactionProgress').addEventListener('input', e => {
  tweenId++;
  updateProgress(e.target.value);
});
document.getElementById('step0').addEventListener('click', () => window.goToStep(0));
