    setCylinderBetween(subBonds[i], pos.c, pos.subs[i]);
  }
  setCylinderBetween(nuSolidBond, pos.nu, pos.c);
  setCylinderBetween(xSolidBond, pos.c, pos.x);
  setMeshOpacity(nuSolidBond, clamp01((currentProgress - 0.52) / 0.36));
  setMeshOpacity(xSolidBond, clamp01(1 - currentProgress / 0.46));
  setDashedLine(nuPartial, pos.nu, pos.c, wMid * 0.95);
