    surfaceB.visible = false;
  }

  const oR = easeOpacity(1 - currentProgress / 0.42);
  const oTS = easeOpacity(wMid * 1.15);
  const oP = easeOpacity((currentProgress - 0.58) / 0.42);
  setGroupOpacity(skelReact.group, oR);
  setGroupOpacity(skelTS.group, oTS);
  setGroupOpacity(skelProd.group, oP);
  setLabelOpacity(skelReact.labels, oR);
  setLabelOpacity(skelTS.labels, oTS);
  setLabelOpacity(skelProd.labels, oP);

  progressMarker.position.set(guideX, THREE.MathUtils.lerp(guideTop, guideBot, currentProgress), skelZ);

  if (mapGeomLabel) {
    mapGeomLabel.div.innerHTML = currentProgress > 0.35 && currentProgress < 0.65 ? '<b>Planar</b>' : '<b>Tetrahedral</b>';
