const BLUE = '#6f83d7';
const CARBON = 0x6f8e80;
const SUB = 0xaeb99b;
const zMol = 0.0;
const zDraw = 0.34;

function C(hex) { return new THREE.Color(hex); }
function clamp01(v) { return Math.max(0, Math.min(1, v)); }

const rowGroups = [];
const allStageLabels = [];

function materialSurface(opacity = 0.64) {
  return new THREE.MeshPhongMaterial({
    vertexColors: true,
    transparent: true,
    opacity,
    shininess: 88,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}

function materialAtom(color) {
  return new THREE.MeshPhongMaterial({ color, shininess: 58 });
}

function metaballGeometry(balls, origin, rings = 34, segs = 68) {
  const positions = [];
  const colors = [];
  const indices = [];
  const o = origin.clone();

  for (let iy = 0; iy <= rings; iy++) {
    const phi = Math.PI * iy / rings;
    const sp = Math.sin(phi);
    const cp = Math.cos(phi);
    for (let ix = 0; ix <= segs; ix++) {
      const th = Math.PI * 2 * ix / segs;
      const dir = new THREE.Vector3(Math.cos(th) * sp, cp, Math.sin(th) * sp);
      let sMax = 0.05;

      for (const b of balls) {
        const oc = o.clone().sub(b.pos);
        const Bq = 2 * dir.dot(oc);
        const Cq = oc.dot(oc) - b.r * b.r;
        const disc = Bq * Bq - 4 * Cq;
        if (disc >= 0) {
          const s = (-Bq + Math.sqrt(disc)) / 2;
          if (s > sMax) sMax = s;
        }
      }

      const p = o.clone().addScaledVector(dir, sMax * 1.035);
      positions.push(p.x, p.y, p.z);

      const cc = new THREE.Color(0, 0, 0);
      let total = 0;
      for (const b of balls) {
        const rel = Math.max(0.03, p.distanceTo(b.pos) / b.r);
        const w = Math.pow(1 / rel, 4.2) * (b.weight || 1);
        cc.add(C(b.color).multiplyScalar(w));
        total += w;
      }
      cc.multiplyScalar(1 / Math.max(total, 0.0001));
      colors.push(cc.r, cc.g, cc.b);
    }
  }

  for (let iy = 0; iy < rings; iy++) {
    for (let ix = 0; ix < segs; ix++) {
      const a = iy * (segs + 1) + ix;
      const b = a + 1;
      const c = a + (segs + 1);
      const d2 = c + 1;
      indices.push(a, c, b, b, c, d2);
    }
  }

  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  g.computeBoundingBox();
  g.computeBoundingSphere();
  return g;
}

function weightedOrigin(balls) {
  const out = new THREE.Vector3();
  let total = 0;
  for (const b of balls) {
    const w = b.r * b.r * (b.weight || 1);
    out.addScaledVector(b.pos, w);
    total += w;
  }
  return out.multiplyScalar(1 / Math.max(total, 0.001));
}

function makeSurface(balls, opacity = 0.64) {
  const mesh = new THREE.Mesh(metaballGeometry(balls, weightedOrigin(balls)), materialSurface(opacity));
  mesh.renderOrder = 1;
  scene.add(mesh);
  return mesh;
}

function makeRedIon(pos, r) {
  const geom = new THREE.SphereGeometry(r, 64, 36);
  const mat = new THREE.MeshPhongMaterial({
    color: 0xef7376,
    transparent: true,
    opacity: 0.66,
    shininess: 95,
    depthWrite: false
  });
  const m = new THREE.Mesh(geom, mat);
  m.position.copy(pos);
  m.renderOrder = 1;
  scene.add(m);
  return m;
}

function makeAtom(pos, r, color) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 40, 24), materialAtom(color));
  m.position.copy(pos);
  m.renderOrder = 4;
  scene.add(m);
  return m;
}

function makeBond(a, b, radius = 0.014, color = BOND, opacity = 0.72) {
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, 1, 16),
    new THREE.MeshPhongMaterial({ color, transparent: opacity < 1, opacity, shininess: 38 })
  );
  setCylinder(mesh, a, b);
  mesh.renderOrder = 3;
  scene.add(mesh);
  return mesh;
}

function setCylinder(mesh, a, b) {
  const mid = a.clone().add(b).multiplyScalar(0.5);
  const dir = b.clone().sub(a);
  const len = Math.max(dir.length(), 0.001);
  mesh.position.copy(mid);
  mesh.scale.set(1, len, 1);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
}

function line(points, color = BLACK, opacity = 1, dashed = false, parent = scene) {
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.055, gapSize: 0.04, transparent: true, opacity })
    : new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), mat);
  if (dashed) l.computeLineDistances();
  parent.add(l);
  return l;
}

function dashedBond(a, b, color = 0xff0095) {
  return line([a, b], color, 1, true);
}

function wedge(c, end, width = 0.10, color = BLACK, parent = scene) {
  const dir = end.clone().sub(c).normalize();
  const perp = new THREE.Vector3(-dir.y, dir.x, 0).multiplyScalar(width);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute([
    c.x, c.y, c.z,
    end.x + perp.x, end.y + perp.y, end.z,
    end.x - perp.x, end.y - perp.y, end.z
  ], 3));
  g.setIndex([0, 1, 2]);
  g.computeVertexNormals();
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  parent.add(m);
  return m;
}

function hashedWedge(c, end, color = BLACK, parent = scene) {
  const g = new THREE.Group();
  parent.add(g);
  const dir = end.clone().sub(c);
  const n = new THREE.Vector3(-dir.y, dir.x, 0).normalize();
  for (let i = 1; i <= 7; i++) {
    const f = i / 8;
    const mid = c.clone().lerp(end, f);
    const half = 0.015 + 0.06 * f;
    line([mid.clone().addScaledVector(n, -half), mid.clone().addScaledVector(n, half)], color, 1, false, g);
  }
  return g;
}

function arrowDown(x, yTop, yBot) {
  line([new THREE.Vector3(x, yTop, zDraw), new THREE.Vector3(x, yBot, zDraw)], BLACK);
  line([new THREE.Vector3(x, yBot, zDraw), new THREE.Vector3(x - 0.07, yBot + 0.16, zDraw)], BLACK);
  line([new THREE.Vector3(x, yBot, zDraw), new THREE.Vector3(x + 0.07, yBot + 0.16, zDraw)], BLACK);
}

function setOpacityObject(obj, factor) {
  obj.traverse(o => {
    if (o.material) {
      const arr = Array.isArray(o.material) ? o.material : [o.material];
      for (const mat of arr) {
        if (mat.userData.baseOpacity == null) mat.userData.baseOpacity = mat.opacity == null ? 1 : mat.opacity;
        mat.transparent = true;
        mat.opacity = mat.userData.baseOpacity * factor;
      }
    }
  });
}

function addToRow(row, ...objects) {
  row.objects.push(...objects.filter(Boolean));
}

function makeRow(name) {
  const row = { name, objects: [], labels: [] };
