const midNu = new THREE.Vector3(-3.15, 0.15, zMol);
const midC = new THREE.Vector3(-2.15, 0.15, zMol + 0.02);
const midX = new THREE.Vector3(-1.12, 0.15, zMol);
const midSubs = [
  new THREE.Vector3(-2.15, 0.65, zMol + 0.02),
  new THREE.Vector3(-2.15, -0.34, zMol + 0.02),
