const midSurface = makeSurface([
  { pos: midNu, r: 0.70, color: RED, weight: 1.55 },
  { pos: new THREE.Vector3(-2.70, 0.15, zMol), r: 0.52, color: ORANGE, weight: 0.95 },
  { pos: midC, r: 0.68, color: GREEN, weight: 1.28 },
  { pos: new THREE.Vector3(-1.62, 0.15, zMol), r: 0.55, color: YELLOW, weight: 0.95 },
