function skeletalReactants() {
  const g = new THREE.Group();
  scene.add(g);
  const c = new THREE.Vector3(1.85, 1.82, zDraw);
  line([c, new THREE.Vector3(2.33, 1.82, zDraw)], BLACK, 1, false, g);
  line([c, new THREE.Vector3(1.58, 1.42, zDraw)], BLACK, 1, false, g);
  wedge(c, new THREE.Vector3(1.62, 2.19, zDraw), 0.075, BLACK, g);
  hashedWedge(c, new THREE.Vector3(1.46, 2.13, zDraw), BLACK, g);
  return g;
}

function skeletalTS() {
  const g = new THREE.Group();
  scene.add(g);
  const c = new THREE.Vector3(1.85, 0.12, zDraw);
  line([new THREE.Vector3(0.68, 0.12, zDraw), c], 0xff0095, 1, true, g);
  line([c, new THREE.Vector3(3.02, 0.12, zDraw)], 0xff0095, 1, true, g);
  line([c, new THREE.Vector3(1.85, -0.28, zDraw)], BLACK, 1, false, g);
  wedge(c, new THREE.Vector3(1.73, 0.50, zDraw), 0.055, BLACK, g);
  hashedWedge(c, new THREE.Vector3(1.97, 0.52, zDraw), BLACK, g);
  const lx = 0.40, rx = 3.28, y0 = -0.22, y1 = 0.60;
  line([new THREE.Vector3(lx, y0, zDraw), new THREE.Vector3(lx, y1, zDraw)], BLACK, 1, false, g);
  line([new THREE.Vector3(lx, y1, zDraw), new THREE.Vector3(lx + 0.08, y1, zDraw)], BLACK, 1, false, g);
  line([new THREE.Vector3(lx, y0, zDraw), new THREE.Vector3(lx + 0.08, y0, zDraw)], BLACK, 1, false, g);
  line([new THREE.Vector3(rx, y0, zDraw), new THREE.Vector3(rx, y1, zDraw)], BLACK, 1, false, g);
  line([new THREE.Vector3(rx, y1, zDraw), new THREE.Vector3(rx - 0.08, y1, zDraw)], BLACK, 1, false, g);
  line([new THREE.Vector3(rx, y0, zDraw), new THREE.Vector3(rx - 0.08, y0, zDraw)], BLACK, 1, false, g);
  return g;
}

function skeletalProducts() {
  const g = new THREE.Group();
  scene.add(g);
  const c = new THREE.Vector3(1.75, -1.58, zDraw);
  line([new THREE.Vector3(1.27, -1.58, zDraw), c], BLACK, 1, false, g);
