const slider = document.getElementById('reactionProgress');
const dimBox = document.getElementById('dimRows');
const btns = [document.getElementById('step0'), document.getElementById('step1'), document.getElementById('step2')];

function activeIndexFromProgress(v) {
  if (v < 0.34) return 0;
  if (v < 0.67) return 1;
  return 2;
}

function updateHighlight(v) {
  const idx = activeIndexFromProgress(Number(v));
  btns.forEach((b, i) => b.classList.toggle('active', i === idx));
  const dim = dimBox.checked;
  rowGroups.forEach((row, i) => {
    const factor = dim ? (i === idx ? 1 : 0.28) : 1;
    row.objects.forEach(o => setOpacityObject(o, factor));
    row.labels.forEach(l => {
      l.div.style.opacity = String(dim ? (i === idx ? 1 : 0.30) : 1);
      l.div.style.fontWeight = i === idx && dim ? '700' : '';
    });
  });
}

function stagePopup(i) {
  const titles = [
    'Reactants: tetrahedral substrate',
    'Transition state: planar carbon',
    'Products: inverted tetrahedron'
  ];
  const bodies = [
    'Nu:⁻ is a separate electron-rich red sphere. The alkyl halide is still tetrahedral and bonded to X.',
    'Nu and X lie opposite one another with partial dashed bonds. The central carbon and three substituents are planar; red potential appears at both endpoints.',
    'The Nu–C bond is formed and X:⁻ has separated. The tetrahedral arrangement is inverted relative to the reactant.'
  ];
  showPopup(titles[i], bodies[i]);
}

function tweenSliderTo(target) {
  const start = Number(slider.value);
  const t0 = performance.now();
  const dur = 520;
  function step(now) {
    const u = clamp01((now - t0) / dur);
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    const val = start + (target - start) * e;
    slider.value = val.toFixed(2);
    updateHighlight(val);
    if (u < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

slider.addEventListener('input', e => updateHighlight(e.target.value));
dimBox.addEventListener('change', () => updateHighlight(slider.value));
btns[0].addEventListener('click', () => { tweenSliderTo(0); stagePopup(0); });
btns[1].addEventListener('click', () => { tweenSliderTo(0.5); stagePopup(1); });
btns[2].addEventListener('click', () => { tweenSliderTo(1); stagePopup(2); });

updateHighlight(0);
